/** Actual released tile/group resolution, block bounds/collision and block/offset rays. */
public final class TrapdoorGeometryLegacyOracle {
 private static final BlockPos ORIGIN=new BlockPos(16,64,-16);
 private static final double[] POSES={0,.125,.5,.875,1};
 private static JsonArray numbers(double... values){JsonArray out=new JsonArray();for(double value:values)out.add(value);return out;}
 private static JsonArray corners(double[][] values){JsonArray out=new JsonArray();for(double[] value:values)out.add(numbers(value));return out;}
 private static JsonArray box(AxisAlignedBB b){return numbers(b.minX,b.minY,b.minZ,b.maxX,b.maxY,b.maxZ);}
 private static JsonElement hit(RayTraceResult h){if(h==null)return JsonNull.INSTANCE;JsonObject out=new JsonObject();out.add("point",numbers(h.hitVec.x,h.hitVec.y,h.hitVec.z));out.addProperty("face",h.sideHit.getIndex());return out;}
 private static NBTTagCompound tag(BlockPos pos,int mode,boolean diagonal,EnumFacing face,boolean inverted,int flags,List<BlockPos> members){NBTTagCompound n=new NBTTagCompound();n.setInteger("x",pos.getX());n.setInteger("y",pos.getY());n.setInteger("z",pos.getZ());n.setInteger("housingTexture",ScreenHousingTextures.DEFAULT_TRAPDOOR);n.setInteger("TrapdoorPosition",mode);n.setBoolean("TrapdoorSliding",(flags&1)!=0);n.setBoolean("TrapdoorCover",!diagonal&&(flags&2)!=0);n.setBoolean("TrapdoorSlideOverSurface",!diagonal&&(flags&4)!=0);n.setBoolean("TrapdoorSlideIntoWall",diagonal&&(flags&4)!=0);n.setInteger("TrapdoorCoverFacing",face.getHorizontalIndex());n.setBoolean("DiagonalReverse",(flags&8)!=0);n.setBoolean("DiagonalRotationFlipped",(flags&16)!=0);n.setInteger("DiagonalFacing",face.getHorizontalIndex());n.setBoolean("DiagonalInverted",inverted);n.setInteger("DiagonalHingeSide",flags%3);n.setInteger("DiagonalGroupFacing",face.getHorizontalIndex());NBTTagList list=new NBTTagList();for(BlockPos member:members)list.appendTag(new NBTTagLong(member.toLong()));n.setTag("TrapdoorAssembly",list);n.setDouble("TrapdoorHinge",(flags&16)==0?-.375:1.9375);n.setDouble("TrapdoorTravel",2.9375);return n;}
 public static void main(String[] args)throws Exception{
  net.minecraft.init.Bootstrap.register();BlockProgrammableTrapdoor regular=new BlockProgrammableTrapdoor();BlockProgrammableDiagonalTrapdoor diagonalBlock=new BlockProgrammableDiagonalTrapdoor();File file=new File(args[0]);file.getAbsoluteFile().getParentFile().mkdirs();Gson gson=new Gson();int profiles=0,boxes=0,rays=0;
  try(PrintWriter out=new PrintWriter(file,"UTF-8")){
   for(boolean diagonal:new boolean[]{false,true})for(int mode=0;mode<3;mode++)for(EnumFacing face:EnumFacing.HORIZONTALS)for(int flags=0;flags<32;flags++){
    boolean inverted=diagonal&&(flags&2)!=0,cover=!diagonal&&(flags&2)!=0,assembly=(flags&8)!=0&&!cover;BlockPos origin=(flags&16)==0?ORIGIN:new BlockPos(29999980,64,-29999980);BlockProgrammableTrapdoor block=diagonal?diagonalBlock:regular;NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(true);List<BlockPos> members=new ArrayList<>();members.add(origin);if(assembly){EnumFacing width=diagonal?face.rotateYCCW():EnumFacing.EAST,along=diagonal?(mode==2?face.getOpposite():EnumFacing.UP):EnumFacing.SOUTH;members.add(origin.offset(width));members.add(origin.offset(along));members.add(origin.offset(width).offset(along));}
    for(int i=0;i<members.size();i++){BlockPos at=members.get(i);EnumFacing peerFace=diagonal&&i>=2&&(flags&16)!=0?face.getOpposite():face;boolean peerInverted=diagonal&&i>=2&&(flags&16)!=0?!inverted:inverted;IBlockState state=block.getDefaultState().withProperty(BlockTrapDoor.FACING,peerFace).withProperty(BlockTrapDoor.HALF,(diagonal?peerInverted:mode==2)?BlockTrapDoor.DoorHalf.TOP:BlockTrapDoor.DoorHalf.BOTTOM);world.setBlockState(at,state,2);TileEntityProgrammableTrapdoor tile=(TileEntityProgrammableTrapdoor)world.getTileEntity(at);tile.readFromNBT(tag(at,mode,diagonal,peerFace,peerInverted,flags,assembly?members:Collections.emptyList()));}
    TileEntityProgrammableTrapdoor tile=(TileEntityProgrammableTrapdoor)world.getTileEntity(origin);if(cover&&(flags&16)!=0){BlockPos opposite=origin.offset(face,3);world.setBlockState(opposite,regular.getDefaultState().withProperty(BlockTrapDoor.FACING,face.getOpposite()),2);((TileEntityProgrammableTrapdoor)world.getTileEntity(opposite)).readFromNBT(tag(opposite,mode,false,face.getOpposite(),false,flags,Collections.emptyList()));}
    List<TileEntityProgrammableTrapdoor> group=tile.group();if(group.size()!=(assembly?4:1))throw new AssertionError("Actual group mismatch");IBlockState state=world.getBlockState(origin);JsonObject record=new JsonObject();record.addProperty("diagonal",diagonal);record.addProperty("position",mode);record.addProperty("turns",BlockProgrammableTrapdoor.quarterTurns(face));record.addProperty("inverted",inverted);record.addProperty("sliding",tile.isSliding());record.addProperty("cover",tile.isCover());record.addProperty("surface",tile.isSlideOverSurface());record.addProperty("intoWall",tile.isSlideIntoWall());record.addProperty("hinge",tile.motionHinge());record.addProperty("travel",tile.motionTravel());record.addProperty("overhang",tile.coverOverhang());record.addProperty("groupSize",group.size());record.addProperty("reverse",diagonal&&((TileEntityProgrammableDiagonalTrapdoor)tile).rotationReverse(group));record.addProperty("closedReverse",diagonal&&((TileEntityProgrammableDiagonalTrapdoor)tile).rotationReverse(Collections.emptyList()));record.addProperty("lift",diagonal?((TileEntityProgrammableDiagonalTrapdoor)tile).slideLiftDirection(group):1);record.add("origin",numbers(origin.getX(),origin.getY(),origin.getZ()));JsonArray poses=new JsonArray();for(double pose:POSES){double[][] v=new double[8][3];if(diagonal)BlockProgrammableDiagonalTrapdoor.writeCorners(state,(TileEntityProgrammableDiagonalTrapdoor)tile,pose,group,v);else tile.writeCorners(state,pose,v);poses.add(corners(v));}record.add("corners",poses);JsonArray endpoints=new JsonArray();
    for(boolean open:new boolean[]{false,true}){state=state.withProperty(BlockTrapDoor.OPEN,open);world.states.put(origin,state);AxisAlignedBB bounds=state.getBoundingBox(world,origin);JsonObject endpoint=new JsonObject();endpoint.addProperty("open",open);endpoint.add("bounds",box(bounds));List<AxisAlignedBB> collision=new ArrayList<>();block.addCollisionBoxToList(state,world,origin,new AxisAlignedBB(origin.getX()-16,origin.getY()-16,origin.getZ()-16,origin.getX()+16,origin.getY()+16,origin.getZ()+16),collision,null,true);JsonArray collisionData=new JsonArray();for(AxisAlignedBB b:collision)collisionData.add(box(b));endpoint.add("collision",collisionData);boxes+=collision.size();double cx=(bounds.minX+bounds.maxX)/2+origin.getX(),cy=(bounds.minY+bounds.maxY)/2+origin.getY(),cz=(bounds.minZ+bounds.maxZ)/2+origin.getZ();JsonArray traces=new JsonArray();for(int ray=0;ray<16;ray++){Vec3d start,end;if(ray<6){int axis=ray/2;double sign=(ray&1)==0?-1:1;start=new Vec3d(cx+(axis==0?sign*12:0),cy+(axis==1?sign*12:0),cz+(axis==2?sign*12:0));end=new Vec3d(cx,cy,cz);}else if(ray<12){int axis=(ray-6)/2;double sign=(ray&1)==0?-1:1;start=new Vec3d(cx,cy,cz);end=new Vec3d(cx+(axis==0?sign*12:0),cy+(axis==1?sign*12:0),cz+(axis==2?sign*12:0));}else if(ray==12){start=new Vec3d(origin.getX()+bounds.minX-(bounds.maxX-bounds.minX),origin.getY()+bounds.minY-(bounds.maxY-bounds.minY),origin.getZ()+bounds.minZ-(bounds.maxZ-bounds.minZ));end=new Vec3d(origin.getX()+bounds.maxX+(bounds.maxX-bounds.minX),origin.getY()+bounds.maxY+(bounds.maxY-bounds.minY),origin.getZ()+bounds.maxZ+(bounds.maxZ-bounds.minZ));}else{double delta=ray==13?1e-10:ray==14?.0003:.0004;start=new Vec3d(origin.getX()+bounds.minX-delta/2,origin.getY()+bounds.minY-.25,cz);end=new Vec3d(start.x+delta,origin.getY()+bounds.maxY+.25,cz);}JsonObject trace=new JsonObject();trace.add("start",numbers(start.x,start.y,start.z));trace.add("end",numbers(end.x,end.y,end.z));trace.add("block",hit(state.collisionRayTrace(world,origin,start,end)));trace.add("offset",hit(diagonal?state.collisionRayTrace(world,origin,start,end):bounds.offset(origin).calculateIntercept(start,end)));traces.add(trace);rays++;}endpoint.add("rays",traces);endpoints.add(endpoint);}
    record.add("endpoints",endpoints);out.println(gson.toJson(record));profiles++;
   }
  }golden(file);System.out.println("Trapdoor actual Forge geometry PASS profiles="+profiles+" collisionBoxes="+boxes+" rayPairs="+rays+" regular/diagonal, group pivots, covers/seams, surface/into-wall, inversion/facing, inside/tie/nearparallel and large coordinates");
 }
 private static void golden(File file)throws Exception{java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");for(String line:java.nio.file.Files.readAllLines(file.toPath(),java.nio.charset.StandardCharsets.UTF_8)){digest.update(line.getBytes(java.nio.charset.StandardCharsets.UTF_8));digest.update((byte)'\n');}StringBuilder actual=new StringBuilder();for(byte b:digest.digest())actual.append(String.format(Locale.ROOT,"%02x",b&255));if(!actual.toString().equals("8a42bcaaf69b3d04eec8af9f8bb7a09859860019ea4273f498cc027eb00961ca"))throw new AssertionError("Released Trapdoor geometry changed: "+actual);}

}
